"""Regenerate the reference module from the archived calculation, without network access."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
r=json.loads((ROOT/'data/hypothesis_comparison/visual_data.json').read_text(encoding='utf-8'))
r['certificates']=json.loads((ROOT/'proof/hypothesis/certificates.json').read_text(encoding='utf-8'))
r['provenance']={'paper':'https://arxiv.org/html/2002.09262v3','table':3,'thetaH':.1,'mH_GeV':125.1,'recalibrated':True,'bottomIncluded':False,'physicalUncertainty':'unquantified','source_sha256':r['source_sha256'],'potential_engine_sha256':r['potential_engine_sha256'],'convention':r['potential_convention']}
(ROOT/'src/modules/hypothesis_reference.mjs').write_text('/* Generated by tools/make_hypothesis_reference.py; archived numerical reconstruction. */\nexport const HCX_REFERENCE='+json.dumps(r,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
